var FIELDS = [
  ["Vendor","Vendor"],["Billing ID","Billing ID"],["Service Account","Service Account"],
  ["Meter ID","Meter ID"],["Utility","Utility"],["Type","Type"],
  ["Last Bill","Last Bill"],
  ["Vendor Code","Vendor Code"],["Account ID","id"]
];
function esc(s){ return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
function render(){
  var va = (appsmith.model && appsmith.model.va) || {};
  var html = '<div class="hd"><h2>Virtual Account Details</h2><span class="x" id="closeX">×</span></div><div class="grid">';
  FIELDS.forEach(function(f){
    var v = va[f[1]];
    var disp = (v == null || v === "") ? "—" : esc(v);
    html += '<div class="fld"><div class="lbl">'+f[0]+'</div><div class="val">'+disp+'</div></div>';
  });
  html += '</div>';
  var root = document.getElementById("root"); if(!root) return;
  root.innerHTML = html;
  var x = document.getElementById("closeX");
  if (x) x.onclick = function(){ appsmith.triggerEvent("onClose"); };
}
appsmith.onReady(function(){ render(); appsmith.onModelChange(render); });

